```javascript
// cache.js
class ProfileCache {
  constructor(ttl = 300000) { // 5 min default
    this.cache = new Map();
    this.ttl = ttl;
  }

  set(key, value) {
    this.cache.set(key, {
      data: value,
      expires: Date.now() + this.ttl
    });
  }

  get(key) {
    const item = this.cache.get(key);
    if (!item) return null;
    if (Date.now() > item.expires) {
      this.cache.delete(key);
      return null;
    }
    return item.data;
  }

  invalidate(key) {
    this.cache.delete(key);
  }
}

module.exports = new ProfileCache();
